// Read text contents from page "00 · Start Here 设计任务" (id: 0:1)
const startPage = figma.root.children.find(p => p.id === '0:1' || p.name.includes('Start Here'));
if (!startPage) {
  return { error: 'Start Here page not found' };
}

function extractTexts(node) {
  let texts = [];
  if (node.type === 'TEXT') {
    texts.push({ name: node.name, text: node.characters });
  }
  if ('children' in node) {
    for (const child of node.children) {
      texts = texts.concat(extractTexts(child));
    }
  }
  return texts;
}

const allTexts = extractTexts(startPage);
return {
  pageName: startPage.name,
  textCount: allTexts.length,
  texts: allTexts.map(t => `${t.name}: ${t.text}`).slice(0, 100)
};

// Let's inspect the components page (id: "1:3" or "02 · Components 组件库") and the foundations page (id: "1:2" or "01 · Foundations 视觉规范") and media page (id: "1:4" or "04 · Media 素材库")
const foundPage = figma.root.children.find(p => p.id === '1:2' || p.name.includes('Foundations'));
const compPage = figma.root.children.find(p => p.id === '1:3' || p.name.includes('Components'));
const mediaPage = figma.root.children.find(p => p.id === '1:4' || p.name.includes('Media'));
const workspacePage = figma.root.children.find(p => p.id === '3:2' || p.name.includes('Workspace'));

function getChildrenShort(page) {
  if (!page) return 'not found';
  return page.children.map(c => ({ id: c.id, name: c.name, type: c.type }));
}

return {
  foundations: getChildrenShort(foundPage),
  components: getChildrenShort(compPage),
  media: getChildrenShort(mediaPage),
  workspace: getChildrenShort(workspacePage)
};

// Let's inspect what is inside "Components" frame (id: "1:19") and "Media" frame (id: "1:257")
const compNode = figma.getNodeById("1:19");
const mediaNode = figma.getNodeById("1:257");

function getSubChildren(node) {
  if (!node || !node.children) return [];
  return node.children.map(c => ({ id: c.id, name: c.name, type: c.type }));
}

return {
  compChildren: getSubChildren(compNode),
  mediaChildren: getSubChildren(mediaNode)
};

// Let's list the children of "Product & promo photos" (1:261), "Reviewers" (1:327) and "Icons" (1:335) to see what images/icons are available
const photoFrame = figma.getNodeById("1:261");
const reviewerFrame = figma.getNodeById("1:327");
const iconFrame = figma.getNodeById("1:335");

function getChildrenDetail(node) {
  if (!node || !node.children) return [];
  return node.children.map(c => ({ id: c.id, name: c.name, type: c.type }));
}

return {
  photos: getChildrenDetail(photoFrame),
  reviewers: getChildrenDetail(reviewerFrame),
  icons: getChildrenDetail(iconFrame)
};

// Inspect Button and Text Field properties in 02 · Components
const btn = figma.getNodeById("1:23");
const tf = figma.getNodeById("1:26");

function inspectNode(n) {
  return {
    id: n.id,
    name: n.name,
    width: n.width,
    height: n.height,
    fills: n.fills,
    strokes: n.strokes,
    cornerRadius: n.cornerRadius,
    paddingLeft: n.paddingLeft,
    paddingRight: n.paddingRight,
    paddingTop: n.paddingTop,
    paddingBottom: n.paddingBottom,
    primaryAxisAlignItems: n.primaryAxisAlignItems,
    counterAxisAlignItems: n.counterAxisAlignItems,
    children: n.children ? n.children.map(c => ({ id: c.id, name: c.name, type: c.type, characters: c.characters, fills: c.fills, fontSize: c.fontSize, fontName: c.fontName })) : []
  };
}

return {
  button: inspectNode(btn),
  textField: inspectNode(tf)
};

// Let's inspect the "01 · Foundations" page to see what's in there.
const foundPage = figma.root.children.find(p => p.id === '1:2' || p.name.includes('Foundations'));
if (foundPage && foundPage.children.length > 0) {
  return {
    children: foundPage.children.map(c => ({ id: c.id, name: c.name, type: c.type }))
  };
} else if (foundPage) {
  // Wait, the children was empty [] in previous call!
  // Let's verify if there is any other way. Maybe it's empty, or contains hidden layers? Let's check foundPage itself
  return {
    foundPageName: foundPage.name,
    foundPageId: foundPage.id,
    childCount: foundPage.children.length
  };
}
return { foundPage: 'not found' };

// Let's create the Workspace page if it does not have components.
// Actually, workspace is 3:2. Let's see what is inside 3:2. It had 0 children.
// Let's first make sure we can load all fonts we'll need:
// - Inter Regular, Medium, Semi Bold, Bold etc.
// Let's check what fonts are available or just load standard ones.
// Figma font loading is standard.
// Let's write a helper that can clone components or create standard styles.
// Let's check if the components in "02 · Components" are main components or instances,
// they are COMPONENT. We can create instances of them in Workspace.
// Wait! Let's examine what needs to be created on Workspace page.
// The instructions say: "Build exactly the 7 frames below, named exactly as listed (one page / step per frame), and wire them as a clickable prototype with the listed links."
// 7 frames:
// 1. "01_Home"
// 2. "02_Products"
// 3. "03_Product_Details"
// 4. "04_Shopping_Cart"
// 5. "05_Checkout_Address"
// 6. "06_Checkout_Shipping"
// 7. "07_Checkout_Payment"
// Let's define the page dimensions: 1440 width. Height can vary based on content.
// Header is required on every page:
// - wordmark "cyber" (leads to 01_Home)
// - search field "Search" with Icon_Search
// - navigation Home (current on Home? wait, the brief says current: Home for Home, but wait, the brief says "navigation Home · About · Contact Us · Blog · wishlist (Icon_Heart) · cart (Icon_Cart) · account (Icon_User) · current: Home". Let's check if current is Home on all pages or if it depends on page. It says "current: Home" for all of them. Let's keep it consistent.)
// - cart icon leads to 04_Shopping_Cart
//
// Let's design the Workspace (3:2 page).
// First, let's load Inter fonts. We must do figma.loadFontAsync before changing/creating text.
// Let's test font loading and a small test on Workspace.
return { status: "ready to load fonts and design" };

// Let's find all the icons and photos in 04 · Media (id: 1:4)
const mediaPage = figma.root.children.find(p => p.id === '1:4' || p.name.includes('Media'));
if (!mediaPage) {
  return { error: "Media page not found" };
}

function findLeafNodes(node, depth = 0) {
  let list = [];
  if (node.type === 'FRAME' || node.type === 'GROUP') {
    if (depth > 2 || node.children.length === 0) {
      list.push({ id: node.id, name: node.name, type: node.type });
    } else {
      for (const child of node.children) {
        list = list.concat(findLeafNodes(child, depth + 1));
      }
    }
  } else {
    list.push({ id: node.id, name: node.name, type: node.type });
  }
  return list;
}

const mediaSubNodes = findLeafNodes(mediaPage);
return {
  totalMediaNodes: mediaSubNodes.length,
  mediaNodes: mediaSubNodes.map(m => `${m.name} (${m.type}, ID: ${m.id})`).slice(0, 100)
};

// Let's search inside the children of "04 · Media 素材库" (ID: 1:4).
// Wait, in previous calls we saw page 1:4 has children: [{"id":"1:257","name":"Media","type":"FRAME"}].
// Let's search within "Media" frame (ID: 1:257).
const mediaFrame = figma.getNodeById("1:257");
if (!mediaFrame) {
  return { error: "Media frame not found" };
}

function traverse(node, maxDepth = 4, depth = 0) {
  if (depth > maxDepth) return { id: node.id, name: node.name, type: node.type, tooDeep: true };
  let info = { id: node.id, name: node.name, type: node.type };
  if (node.children) {
    info.children = node.children.map(c => traverse(c, maxDepth, depth + 1));
  }
  return info;
}

const tree = traverse(mediaFrame, 2);
return { tree };

// We have a fully mapped tree of Media and Components!
// Now we need to start writing our script to build the entire design on the "03 · Workspace" page.
// First, let's switch current page to Workspace (3:2) or make sure we find it.
// Let's create a solid foundation script.
// Let's write a JavaScript helper that can:
// 1. Set current page to Workspace.
// 2. Clear any existing children in Workspace to avoid duplicates if run multiple times (it's currently empty anyway, but good practice).
// 3. Keep standard styles, fonts.
//
// Let's check what fonts we need to load.
// We need 'Inter' with styles:
// - Regular
// - Medium
// - Semi Bold
// - Bold
// Let's load them inside the figma-use environment:
