//   figma.loadFontAsync({ family: 'Inter', style: 'Medium' }),
//   figma.loadFontAsync({ family: 'Inter', style: 'Semi Bold' }),
//   figma.loadFontAsync({ family: 'Inter', style: 'Bold' }),
// ]);
//
// Let's design the layout and spacing:
// Desktop web: 1440 wide.
// Let's create a reusable Header:
// Height: 88px.
// Contents:
// - wordmark "cyber" (large text, Inter Bold, 24px)
// - Search field (Input component style or custom container 372px wide, containing Icon_Search + placeholder "Search")
// - Navigation links: Home, About, Contact Us, Blog (Inter Medium 16px, spaced, current is Home with slightly darker color, others gray)
// - Icons: Icon_Heart, Icon_Cart, Icon_User (spaced, right side)
// Let's write a script that does this! Let's do it incrementally and robustly.

const code = `
async function run() {
  const ws = figma.root.children.find(p => p.id === '3:2' || p.name.includes('Workspace'));
  if (!ws) {
    return { error: 'Workspace page not found' };
  }
  await figma.setCurrentPageAsync(ws);
  return { success: true, msg: 'Page set to Workspace' };
}
run();
`;

