// Let's create the script to build all components, layouts, and wire them!
// To make it very clean, let's write a comprehensive Figma Plugin API script to do this.
// We'll write the script to run in Workspace page and build all 7 frames.
// Since we have the IDs of all the icons and photos, we can instantiate them as component instances!
// Let's check if the components in Media are COMPONENT types. Yes:
// - "Icon_Search" component ID is "1:215"
// - "Photo_Hero_Phone" component ID is "1:236"
// - etc.
// Let's write a JS function that instantiates these assets safely:
// function createInstance(id) {
//   const component = figma.getNodeById(id);
//   if (component && component.type === 'COMPONENT') {
//     return component.createInstance();
//   }
//   // Fallback: search by name
//   const node = findComponentByName(id);
//   if (node) return node.createInstance();
//   return null;
// }
// Let's define the 7 frames with their positions:
// Frame width: 1440.
// Heights:
// - 01_Home: 4500
// - 02_Products: 1800
// - 03_Product_Details: 2800
// - 04_Shopping_Cart: 1200
// - 05_Checkout_Address: 1200
// - 06_Checkout_Shipping: 1200
// - 07_Checkout_Payment: 1400
// We can arrange them side by side with 100px gap, so x-coordinates are:
// - 01_Home: x = 0, y = 0
// - 02_Products: x = 1540, y = 0
// - 03_Product_Details: x = 3080, y = 0
// - 04_Shopping_Cart: x = 4620, y = 0
// - 05_Checkout_Address: x = 6160, y = 0
// - 06_Checkout_Shipping: x = 7700, y = 0
// - 07_Checkout_Payment: x = 9240, y = 0
//
// Let's write a powerful script to generate all 7 pages. Let's do this in a single or modular run to ensure they are created correctly and prototype links are set up.
// Let's first test the creation of the 7 basic frames and standard headers/footers, then we fill in the contents.
// Let's design a robust script.

const mainScript = `
async function run() {
  const ws = figma.root.children.find(p => p.id === '3:2' || p.name.includes('Workspace'));
  if (!ws) return { error: 'Workspace page not found' };
  await figma.setCurrentPageAsync(ws);

  // Load fonts
  await Promise.all([
    figma.loadFontAsync({ family: 'Inter', style: 'Regular' }),
    figma.loadFontAsync({ family: 'Inter', style: 'Medium' }),
    figma.loadFontAsync({ family: 'Inter', style: 'Semi Bold' }),
    figma.loadFontAsync({ family: 'Inter', style: 'Bold' })
  ]);

  // Clean existing children in Workspace
  for (const child of ws.children) {
    child.remove();
  }

  // Find all components in Media and Buttons
  const assets = {};
  function searchComponents(node) {
    if (node.type === 'COMPONENT') {
      assets[node.name] = node;
    }
    if ('children' in node) {
      for (const child of node.children) {
        searchComponents(child);
      }
    }
  }
  searchComponents(figma.root);

  // Helper to create instances or fallback
  function createAsset(name, fallbackWidth = 100, fallbackHeight = 100) {
    const comp = assets[name];
    if (comp) {
      return comp.createInstance();
    }
    // Create fallback frame with label
    const f = figma.createFrame();
    f.name = name + ' (fallback)';
    f.resize(fallbackWidth, fallbackHeight);
    f.fills = [{ type: 'SOLID', color: { r: 0.9, g: 0.9, b: 0.9 } }];
    const t = figma.createText();
    t.characters = name;
    t.fontSize = 10;
    t.fills = [{ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }];
    f.appendChild(t);
    return f;
  }

  return { success: true, keys: Object.keys(assets) };
}
run();
`;

