// Now let's write a powerful script that creates the 7 frames with their full layouts.
// We can design a single JS file and run it inside figma.currentPage.
// Let's break down the required layouts:
//
// 1. Header component (or layout function):
//    - wordmark "cyber" (Text node) -> on click goes to 01_Home
//    - Search bar: Input field containing search icon and "Search"
//    - Navigation: Home, About, Contact Us, Blog (Home is "active" on active screens)
//    - Icons: Heart, Cart (on click goes to 04_Shopping_Cart), User
//
// 2. Footer component (or layout function):
//    - cyber wordmark, description, and three link columns:
//      - Services: Bonus program · Gift cards · Credit and payment · Service contracts · Non-cash account · Payment
//      - Assistance to the buyer: Find an order · Terms of delivery · Exchange and return of goods · Guarantee · Frequently asked questions · Terms of use of the site
//      - Social: Twitter, Facebook, TikTok, Instagram icons
//
// Let's create these structure components.
//
// To ensure the design looks professional and perfectly formatted, let's write a modular script that will build page by page, starting with the Shared components, then Frame 1, Frame 2, Frame 3, Frame 4, Frame 5, Frame 6, Frame 7.
// Let's write the full setup in a high-fidelity script.

const mainScript = `
async function run() {
  const ws = figma.root.children.find(p => p.id === '3:2' || p.name.includes('Workspace'));
  if (!ws) return { error: 'Workspace page not found' };
  await figma.setCurrentPageAsync(ws);

  // Clear workspace
  for (const child of ws.children) {
    child.remove();
  }

  // Load fonts
  await Promise.all([
    figma.loadFontAsync({ family: 'Inter', style: 'Regular' }),
    figma.loadFontAsync({ family: 'Inter', style: 'Medium' }),
    figma.loadFontAsync({ family: 'Inter', style: 'Semi Bold' }),
    figma.loadFontAsync({ family: 'Inter', style: 'Bold' })
  ]);

  // Find all components in Media and Buttons
  const assets = {};
  function searchComponents(node) {
    if (node.type === 'COMPONENT') {
      assets[node.name] = node;
    }
    if ('children' in node) {
      for (const child of node.children) {
        searchComponents(child);
      }
    }
  }
  searchComponents(figma.root);

  // Color Palette Definitions
  const colors = {
    brand: { r: 0, g: 0, b: 0 }, // Black
    white: { r: 1, g: 1, b: 1 },
    gray50: { r: 0.98, g: 0.98, b: 0.98 },
    gray100: { r: 0.95, g: 0.95, b: 0.95 },
    gray200: { r: 0.9, g: 0.9, b: 0.9 },
    gray300: { r: 0.8, g: 0.8, b: 0.8 },
    gray400: { r: 0.6, g: 0.6, b: 0.6 },
    gray600: { r: 0.3, g: 0.3, b: 0.3 },
    gray900: { r: 0.08, g: 0.08, b: 0.08 },
    accentYellow: { r: 1, g: 0.84, b: 0 },
    accentRed: { r: 0.95, g: 0.2, b: 0.2 },
    accentGreen: { r: 0.1, g: 0.7, b: 0.3 },
    textMain: { r: 0.08, g: 0.08, b: 0.08 },
    textMuted: { r: 0.45, g: 0.45, b: 0.45 },
    borderLight: { r: 0.9, g: 0.9, b: 0.9 }
  };

  // Helper function to set solid fill
  function setFill(node, colorObj, opacity = 1) {
    node.fills = [{ type: 'SOLID', color: colorObj, opacity }];
  }

  // Helper function to set stroke
  function setStroke(node, colorObj, weight = 1) {
    node.strokes = [{ type: 'SOLID', color: colorObj }];
    node.strokeWeight = weight;
  }

  // Helper to place asset inside a frame
  function placeAsset(name, parent, width = null, height = null) {
    const comp = assets[name];
    if (comp) {
      const inst = comp.createInstance();
      if (width !== null && height !== null) {
        inst.resize(width, height);
      }
      parent.appendChild(inst);
      return inst;
    } else {
      // Fallback
      const f = figma.createFrame();
      f.name = name + ' (Missing)';
      f.resize(width || 40, height || 40);
      f.fills = [{ type: 'SOLID', color: { r: 1, g: 0.8, b: 0.8 } }];
      const t = figma.createText();
      t.characters = name;
      t.fontSize = 9;
      f.appendChild(t);
      parent.appendChild(f);
      return f;
    }
  }

  // Helper to create simple text
  function createText(parent, characters, size = 14, style = 'Regular', colorObj = colors.textMain, align = 'LEFT') {
    const t = figma.createText();
    t.fontName = { family: 'Inter', style: style };
    t.characters = characters;
    t.fontSize = size;
    t.fills = [{ type: 'SOLID', color: colorObj }];
    t.textAlignHorizontal = align;
    parent.appendChild(t);
    return t;
  }

  // Helper to create Button variant
  function createCustomButton(textStr, width = 120, height = 48, isSecondary = false) {
    const btn = figma.createFrame();
    btn.name = "Button - " + textStr;
    btn.resize(width, height);
    btn.cornerRadius = 8;
    btn.layoutMode = "HORIZONTAL";
    btn.primaryAxisAlignItems = "CENTER";
    btn.counterAxisAlignItems = "CENTER";

    if (isSecondary) {
      btn.fills = [];
      btn.strokes = [{ type: 'SOLID', color: colors.brand }];
      btn.strokeWeight = 1;
    } else {
      btn.fills = [{ type: 'SOLID', color: colors.brand }];
    }

    const t = figma.createText();
    t.fontName = { family: 'Inter', style: 'Medium' };
    t.characters = textStr;
    t.fontSize = 14;
    t.fills = [{ type: 'SOLID', color: isSecondary ? colors.brand : colors.white }];
    btn.appendChild(t);
    return btn;
  }

  // Main navigation / Header creation function
  function createHeader(activeTab = "Home") {
    const header = figma.createFrame();
    header.name = "Header";
    header.resize(1440, 88);
    header.fills = [{ type: 'SOLID', color: colors.white }];
    header.layoutMode = "HORIZONTAL";
    header.primaryAxisAlignItems = "SPACE_BETWEEN";
    header.counterAxisAlignItems = "CENTER";
    header.paddingLeft = 160;
    header.paddingRight = 160;

    // Wordmark
    const wordmark = createText(header, "cyber", 24, "Bold", colors.brand);
    wordmark.name = "Wordmark";

    // Search bar
    const searchBar = figma.createFrame();
    searchBar.name = "Search Bar";
    searchBar.resize(372, 40);
    searchBar.fills = [{ type: 'SOLID', color: colors.gray100 }];
    searchBar.cornerRadius = 8;
    searchBar.layoutMode = "HORIZONTAL";
    searchBar.counterAxisAlignItems = "CENTER";
    searchBar.paddingLeft = 16;
    searchBar.itemSpacing = 8;

    placeAsset("Icon_Search", searchBar, 20, 20);
    const searchPlaceholder = createText(searchBar, "Search", 14, "Regular", colors.textMuted);
    header.appendChild(searchBar);

    // Nav links
    const nav = figma.createFrame();
    nav.name = "Navigation Links";
    nav.layoutMode = "HORIZONTAL";
    nav.itemSpacing = 32;
    nav.fills = [];

    const tabs = ["Home", "About", "Contact Us", "Blog"];
    for (const tab of tabs) {
      const isActive = tab === activeTab;
      const t = createText(nav, tab, 16, isActive ? "Semi Bold" : "Medium", isActive ? colors.textMain : colors.textMuted);
      t.name = "Nav_" + tab;
    }
    header.appendChild(nav);

    // Right Action Icons
    const actions = figma.createFrame();
    actions.name = "Header Actions";
    actions.layoutMode = "HORIZONTAL";
    actions.itemSpacing = 24;
    actions.counterAxisAlignItems = "CENTER";
    actions.fills = [];

    const heart = placeAsset("Icon_Heart", actions, 24, 24);
    heart.name = "WishlistIcon";
    const cart = placeAsset("Icon_Cart", actions, 24, 24);
    cart.name = "CartIcon";
    const user = placeAsset("Icon_User", actions, 24, 24);
    user.name = "UserIcon";

    header.appendChild(actions);

    // Bottom divider line
    const divider = figma.createLine();
    divider.resize(1440, 0);
    divider.strokes = [{ type: 'SOLID', color: colors.borderLight }];

    const container = figma.createFrame();
    container.name = "Header Container";
    container.resize(1440, 88);
    container.layoutMode = "VERTICAL";
    container.appendChild(header);
    container.appendChild(divider);

    return container;
  }

  // Footer creation function
  function createFooter() {
    const footer = figma.createFrame();
    footer.name = "Footer";
