  // Helper to place asset inside a parent frame
  function placeAsset(name, parent, width = null, height = null) {
    const comp = assets[name];
    if (comp) {
      const inst = comp.createInstance();
      if (width !== null && height !== null) {
        inst.resize(width, height);
      }
      parent.appendChild(inst);
      return inst;
    } else {
      const f = figma.createFrame();
      f.name = name + ' (Missing)';
      f.resize(width || 40, height || 40);
      f.fills = [{ type: 'SOLID', color: { r: 1, g: 0.8, b: 0.8 } }];
      const t = figma.createText();
      t.characters = name;
      t.fontSize = 9;
      f.appendChild(t);
      parent.appendChild(f);
      return f;
    }
  }

  // Helper to create text
  function createText(parent, characters, size = 14, style = 'Regular', colorObj = colors.textMain, align = 'LEFT') {
    const t = figma.createText();
    t.fontName = { family: 'Inter', style: style };
    t.characters = characters;
    t.fontSize = size;
    t.fills = [{ type: 'SOLID', color: colorObj }];
    t.textAlignHorizontal = align;
    parent.appendChild(t);
    return t;
  }

  // Create Button
  function createCustomButton(textStr, width = 120, height = 48, isSecondary = false) {
    const btn = figma.createFrame();
    btn.name = "Button - " + textStr;
    btn.resize(width, height);
    btn.cornerRadius = 8;
    btn.layoutMode = "HORIZONTAL";
    btn.primaryAxisAlignItems = "CENTER";
    btn.counterAxisAlignItems = "CENTER";

    if (isSecondary) {
      btn.fills = [];
      btn.strokes = [{ type: 'SOLID', color: colors.brand }];
      btn.strokeWeight = 1;
    } else {
      btn.fills = [{ type: 'SOLID', color: colors.brand }];
    }

    const t = figma.createText();
    t.fontName = { family: 'Inter', style: 'Medium' };
    t.characters = textStr;
    t.fontSize = 14;
    t.fills = [{ type: 'SOLID', color: isSecondary ? colors.brand : colors.white }];
    btn.appendChild(t);
    return btn;
  }

