// Let's create our base components, Header and Footer, as components so we can reuse them.
// Let's write a script to build Header and Footer, then add them to our Workspace page!
// Wait! To make sure they are real Figma components, we can create them on the page.
// Let's do that! Let's write a script that does:
// 1. Create a component for Header
// 2. Create a component for Footer
//
// Header structure (1440 x 88):
// - Auto layout, horizontal, padding 0 160px. Space between elements.
// - Wordmark text "cyber" (24px, Bold, Black).
// - Search container: Auto layout, horizontal, bg #F5F5F5, border-radius 8, padding 8 16, width 372px. Contains Icon_Search (16x16) and placeholder text "Search" (14px, #A0A0A0).
// - Nav container: Auto layout, horizontal, gap 32px. Links: Home (Medium, 16px, #000000), About, Contact Us, Blog (Medium, 16px, #909090).
// - Actions container: Auto layout, horizontal, gap 24px. Contains Icon_Heart, Icon_Cart, Icon_User.
//
// Footer structure (1440 x 360):
// - Background #000000 (Black).
// - Padding 80px 160px.
// - Auto layout, horizontal, gap 120px.
// - Column 1 (About): "cyber" (white text, Bold, 24px), description "cyber is an online store for phones, wearables and accessories, with free delivery and a one-year guarantee." (14px, #909090, width 250px).
// - Column 2 (Services): "Services" (Bold, 16px, white). Gap 8px. Links: Bonus program, Gift cards, Credit and payment, Service contracts, Non-cash account, Payment. (Regular, 14px, #909090).
// - Column 3 (Assistance): "Assistance to the buyer" (Bold, 16px, white). Gap 8px. Links: Find an order, Terms of delivery, Exchange and return of goods, Guarantee, Frequently asked questions, Terms of use of the site. (Regular, 14px, #909090).
// - Bottom row / column / Social icons: Icon_Twitter, Icon_Facebook, Icon_TikTok, Icon_Instagram (white color/transparent clones). Let's lay them out beautifully.
//
// Let's write the code for Header and Footer components now!

const code = `
async function buildBaseComponents() {
  await Promise.all([
    figma.loadFontAsync({ family: 'Inter', style: 'Regular' }),
    figma.loadFontAsync({ family: 'Inter', style: 'Medium' }),
    figma.loadFontAsync({ family: 'Inter', style: 'Semi Bold' }),
    figma.loadFontAsync({ family: 'Inter', style: 'Bold' }),
  ]);

  const ws = figma.root.children.find(p => p.id === '3:2' || p.name.includes('Workspace'));
  await figma.setCurrentPageAsync(ws);

  // Helper to clone icons
  function cloneIcon(id, size = 24, forceColor = null) {
    const original = figma.getNodeById(id);
    if (!original) {
      // Create a fallback rectangle/placeholder
      const rect = figma.createFrame();
      rect.resize(size, size);
      return rect;
    }
    const clone = original.clone();
    clone.resize(size, size);
    if (forceColor) {
      // Find all vector-like things and color them
      const recolor = (node) => {
        if (node.fills && node.fills.length > 0 && node.fills[0].type === 'SOLID') {
          node.fills = [{ type: 'SOLID', color: forceColor }];
        }
        if (node.strokes && node.strokes.length > 0 && node.strokes[0].type === 'SOLID') {
          node.strokes = [{ type: 'SOLID', color: forceColor }];
        }
        if (node.children) node.children.forEach(recolor);
      };
      recolor(clone);
    }
    return clone;
  }

  // Create Header Component
  const headerComp = figma.createComponent();
  headerComp.name = "Header_Main";
  headerComp.resize(1440, 88);
  headerComp.layoutMode = "HORIZONTAL";
  headerComp.primaryAxisAlignItems = "SPACE_BETWEEN";
  headerComp.counterAxisAlignItems = "CENTER";
  headerComp.paddingLeft = 160;
