  search.cornerRadius = 8;
  header.appendChild(search);

  homeFrame.appendChild(header);

  return { frameId: homeFrame.id };
}

return await buildHomePage();

async function run() {
  const ws = figma.root.children.find(p => p.id === '3:2' || p.name.includes('Workspace'));
  await figma.setCurrentPageAsync(ws);

  // Clear any incomplete nodes in workspace
  while (ws.children.length > 0) {
    ws.children[0].remove();
  }

  return { cleared: true };
}
return await run();
